736: { es: 'Devuelve a {S} y todas las Energías básicas unidas a él a tu mano. Si no tienes Pokémon en Banca, este ataque no hace nada.', f: async x => { if (!x.me.bench.length) return x.cancel(); x.post(async () => { const g = x.g, s = x.att; if (!g.slots(x.me).includes(s) || s.dmg >= g.hp(s)) return; g.removeSlot(s); x.me.hand.push(...s.cards); for (const c of s.energy) { if (g.def(c).basic) { delete c.inPlay; x.me.hand.push(c); } else g.toDiscard(c); } for (const c of s.att) g.toDiscard(c); x.log(`${x.name} vuelve a la mano.`); await newActive(g, x.me); }); } },
