776: { es: 'Puedes descartar todas las Energías Rayo unidas a {S}. Si lo haces, el daño base de este ataque es 80 en vez de 40.', f: async x => { const g = x.g; if (!nE(g, x.att, 'L')) return; const need = x.def && g.hpLeft(x.def) > 40; if (await g.ask(x.me, { kind: 'yesno', title: '¿Descartar todas las Energías Rayo para hacer 80?', purpose: need ? 'yes' : 'optionalDiscard' })) { discardAll(x, 'L'); x.dmg = x.base = 80; } } },
