def('Undersea Ruins', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador (antes de atacar), puede lanzar una moneda. Si sale cara, elige 1 de sus Pokémon evolucionados y descarta su carta de Evolución superior (lo involuciona).' + STAD,
  actionCan: (g, p) => !p.ai && g.slots(p).some(s => s.cards.length > 1),
  action: async (g, p) => { if (!(await g.flip(p, 1, 'Ruinas Submarinas'))[0]) return; const ts = g.slots(p).filter(s => s.cards.length > 1); const t = await g.ask(p, { kind: 'slot', title: 'Elige un Pokémon evolucionado', options: ts, purpose: 'scoopDamaged' }); const s = t || ts[0]; const c = s.cards.pop(); g.toDiscard(c); s.fx = {}; g.log(`${g.cn(c)} se descarta: ${g.nm(s)} involuciona.`); }, ai: () => 1 });
def('Power Plant', { stadium: true, once: true, es: 'Una vez durante cada uno de sus turnos, un jugador puede descartar una Energía básica de su mano. Si lo hace, elige una Energía básica de su pila de descartes, la enseña y la pone en su mano.' + STAD,
  actionCan: (g, p) => p.hand.some(c => g.isBasicEnergy(c)) && p.discard.some(c => g.isBasicEnergy(c)),
  action: async (g, p) => { const en = p.hand.filter(c => g.isBasicEnergy(c)); const [e] = await g.ask(p, { kind: 'cards', title: 'Central Eléctrica: descarta una Energía básica', cards: en, min: 1, max: 1, purpose: 'discardHand' }); const pool = p.discard.filter(c => g.isBasicEnergy(c)); g.removeFrom(p.hand, e); g.toDiscard(e); const [c] = await g.ask(p, { kind: 'cards', title: 'Elige una Energía básica de tu descarte', cards: pool, min: 1, max: 1, purpose: 'getEnergy' }); g.removeFrom(p.discard, c); p.hand.push(c); g.log(`${p.name} cambia ${g.cn(e)} por ${g.cn(c)}.`); },
  ai: (g, p) => { const need = new Set(g.slots(p).flatMap(s => g.eff(s).atk.flatMap(a => a.cost))); return p.hand.some(c => g.isBasicEnergy(c) && !need.has(g.def(c).etype)) && p.discard.some(c => g.isBasicEnergy(c) && need.has(g.def(c).etype)) ? 3 : 0; } });
def('Ancient Ruins', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador (antes de atacar), si no ha jugado un Partidario, puede enseñar su mano. Si no hay ningún Partidario en ella, roba una carta.' + STAD,
  actionCan: (g, p) => !p.supporterPlayed && p.deck.length > 1 && !p.hand.some(c => (g.def(c).sub || []).includes('Supporter')),
  action: async (g, p) => { g.log(`${p.name} enseña su mano y roba una carta (Ruinas Antiguas).`); g.draw(p, 1); }, ai: () => 4 });
def('Mystery Zone', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador (antes de atacar), si tiene una carta de Evolución en su mano, puede buscar en su mazo una Energía básica y ponerla en su mano. Luego pone una carta de Evolución de su mano en su mazo y lo baraja.' + STAD,
  actionCan: (g, p) => p.hand.some(c => isEvo(g, c)) && p.deck.some(c => g.isBasicEnergy(c)),
  action: async (g, p) => { await EC().toHandFromDeck(g, p, c => g.isBasicEnergy(c), 1, 'Elige una Energía básica'); const ev = p.hand.filter(c => isEvo(g, c)); if (!ev.length) return; const [c] = await g.ask(p, { kind: 'cards', title: 'Pon una carta de Evolución en tu mazo', cards: ev, min: 1, max: 1, purpose: 'discardHand' }); g.removeFrom(p.hand, c); p.deck.push(c); g.shuffleDeck(p); },
  ai: (g, p) => !p.hand.some(c => g.isEnergy(c)) && p.hand.some(c => isEvo(g, c) && !g.slots(p).some(s => g.baseDef(s).name === g.def(c).from)) ? 3 : 0 });
def('Underground Lake', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador, puede poner un Omanyte o Kabuto de su pila de descartes en su Banca (cuenta como Pokémon Básico).' + STAD,
  actionCan: (g, p) => room(g, p) && p.discard.some(c => /^(Omanyte|Kabuto)$/.test(g.def(c).name)),
  action: async (g, p) => { const l = p.discard.filter(c => /^(Omanyte|Kabuto)$/.test(g.def(c).name)); const [c] = l.length === 1 ? l : await g.ask(p, { kind: 'cards', title: 'Elige un Omanyte o Kabuto', cards: l, min: 1, max: 1, purpose: 'searchBasic' }); g.removeFrom(p.discard, c); p.bench.push(g.mkSlot(p, c)); g.log(`${g.cn(c)} vuelve a la Banca.`); }, ai: () => 5 });
// --- Objetos ---
def('Dual Ball', { es: 'Lanza 2 monedas. Por cada cara, busca en tu mazo un Pokémon Básico (que no sea Bebé), enséñalo y ponlo en tu mano. Baraja tu mazo después.', play: async (g, p) => { const h = await g.flipHeads(p, 2, 'Bola Doble'); if (h) await EC().toHandFromDeck(g, p, c => isPk(g, c) && g.def(c).stage === 0 && !g.def(c).baby, h, `Elige hasta ${h} Pokémon Básicos`); else g.shuffleDeck(p); }, ai: (g, p) => p.bench.length < 3 ? 6 : 2 });
def('Energy Removal 2', { es: 'Lanza una moneda. Si sale cara, elige 1 Energía unida a 1 de los Pokémon de tu rival y descártala.', can: (g, p) => g.slots(g.opp(p)).some(s => s.energy.length), play: async (g, p) => { if (!(await g.flip(p, 1, 'Quitaenergía 2'))[0]) return; const o = g.opp(p); const ts = g.slots(o).filter(s => s.energy.length && !g.effectsBlocked(s, p)); if (!ts.length) return; const t = await g.ask(p, { kind: 'slot', title: 'Elige un Pokémon del rival', options: ts, purpose: 'removeEnergy' }); const s = t || ts[0]; const [c] = await g.ask(p, { kind: 'cards', title: 'Elige la Energía a descartar', cards: s.energy.slice(), min: 1, max: 1, purpose: 'discardOppEnergy', slot: s }); g.removeFrom(s.energy, c); g.toDiscard(c); g.log(`Se descarta ${g.cn(c)} de ${g.nm(s)}.`); }, ai: (g, p) => g.opp(p).active && g.opp(p).active.energy.length ? 7 : 3 });
def('Energy Restore', { es: 'Lanza 3 monedas. Por cada cara, pon una Energía básica de tu pila de descartes en tu mano.', can: (g, p) => p.discard.some(c => g.isBasicEnergy(c)), play: async (g, p) => { const h = await g.flipHeads(p, 3, 'Restaurar Energía'); const l = p.discard.filter(c => g.isBasicEnergy(c)); if (!h) return; const sel = l.length <= h ? l : await g.ask(p, { kind: 'cards', title: `Elige ${h} Energías básicas`, cards: l, min: h, max: h, purpose: 'getEnergy' }); for (const c of sel) { g.removeFrom(p.discard, c); p.hand.push(c); } g.log(`${p.name} recupera ${sel.length} Energía(s).`); }, ai: (g, p) => p.discard.filter(c => g.isBasicEnergy(c)).length >= 2 ? 5 : 0 });
def('Pokémon Reversal', { es: 'Elige 1 de los Pokémon en Banca de tu rival. Lanza una moneda. Si sale cara, cámbialo por el Pokémon Defensor.', can: (g, p) => g.opp(p).bench.length > 0, play: async (g, p) => { const o = g.opp(p); const t = await g.ask(p, { kind: 'slot', title: 'Elige un Pokémon en Banca del rival', options: o.bench.slice(), purpose: 'gustTarget' }); if ((await g.flip(p, 1, 'Cambio Pokémon'))[0]) await g.switchActive(o, t || o.bench[0]); }, ai: (g, p) => g.opp(p).bench.some(s => g.hpLeft(s) <= 30) ? 6 : 0 });
def('Power Charge', { es: 'Lanza una moneda. Si sale cara, baraja 2 Energías de tu pila de descartes en tu mazo (1 si sólo tienes 1).', can: (g, p) => p.discard.some(c => g.isEnergy(c)), play: async (g, p) => { if (!(await g.flip(p, 1, 'Carga de Poder'))[0]) return; const l = p.discard.filter(c => g.isEnergy(c)); const sel = l.length <= 2 ? l : await g.ask(p, { kind: 'cards', title: 'Elige 2 Energías', cards: l, min: 2, max: 2, purpose: 'getEnergy' }); for (const c of sel) g.removeFrom(p.discard, c); p.deck.push(...sel); g.shuffleDeck(p); }, ai: (g, p) => p.deck.length < 15 ? 3 : 1 });
def('Super Energy Removal 2', { es: 'Lanza 2 monedas. Si ambas salen cara, descarta todas las Energías del Pokémon Defensor. Si ambas salen cruz, descarta todas las Energías de tu Pokémon Activo. Si sale 1 cara y 1 cruz, no hace nada.', can: (g, p) => g.opp(p).active && g.opp(p).active.energy.length > 0, play: async (g, p) => { const h = await g.flipHeads(p, 2, 'Superquitaenergía 2'); const s = h === 2 ? g.opp(p).active : h === 0 ? p.active : null; if (!s || (h === 2 && g.effectsBlocked(s, p))) return; for (const c of s.energy.splice(0)) g.toDiscard(c); g.log(`Se descartan todas las Energías de ${g.nm(s)}.`); }, ai: (g, p) => g.opp(p).active.energy.length >= 3 && p.active.energy.length <= 1 ? 6 : 0 });
def('Energy Switch', { es: 'Mueve una Energía básica unida a 1 de tus Pokémon a otro de tus Pokémon.', can: (g, p) => g.slots(p).length > 1 && g.slots(p).some(s => s.energy.some(c => g.def(c).basic)), play: async (g, p) => { const z = g.slots(p).flatMap(s => s.energy.filter(c => g.def(c).basic).map(c => [s, c])); const [c] = await g.ask(p, { kind: 'cards', title: 'Cambio de Energía: elige una Energía básica', cards: z.map(q => q[1]), min: 1, max: 1, purpose: 'payOwnEnergy' }); const q = z.find(q => q[1] === c); const ts = g.slots(p).filter(s => s !== q[0]); const t = await g.ask(p, { kind: 'slot', title: '¿A qué Pokémon la mueves?', options: ts, purpose: 'energyTarget' }); g.removeFrom(q[0].energy, c); (t || ts[0]).energy.push(c); g.log(`Mueve ${g.cn(c)} a ${g.nm(t || ts[0])}.`); },
  ai: (g, p) => { const s = p.active; const b = s && PT.AI.bestAttack(g, p, s, g.opp(p).active); return b && b.miss === 1 && p.bench.some(t => t.energy.some(c => g.def(c).basic)) ? 6 : 0; } });
def('Fast Ball', { es: 'Enseña cartas de tu mazo hasta que salga una carta de Evolución. Ponla en tu mano y baraja las demás en tu mazo.', can: (g, p) => p.deck.length > 0, play: async (g, p) => { for (let i = p.deck.length - 1; i >= 0; i--) { const c = p.deck[i]; if (isEvo(g, c)) { g.removeFrom(p.deck, c); p.hand.push(c); g.log(`Bola Rápida encuentra ${g.cn(c)}.`); break; } } g.shuffleDeck(p); }, ai: (g, p) => p.deck.some(c => isEvo(g, c)) ? 5 : 0 });
def('Friend Ball', { es: 'Elige 1 de los Pokémon de tu rival. Busca en tu mazo un Pokémon Bebé, Básico o una carta de Evolución del mismo tipo, enséñala y ponla en tu mano. Baraja tu mazo después.', play: async (g, p) => { const o = g.opp(p); const ts = g.slots(o); const t = ts.length === 1 ? ts[0] : await g.ask(p, { kind: 'slot', title: 'Bola Amigo: elige un Pokémon del rival', options: ts, purpose: 'friendBall' }); const tys = g.eff(t || ts[0]).types; await EC().toHandFromDeck(g, p, c => isPk(g, c) && g.def(c).types.some(x => tys.includes(x)), 1, 'Elige un Pokémon del mismo tipo'); }, ai: (g, p) => { const tys = g.slots(g.opp(p)).flatMap(s => g.eff(s).types); return p.deck.some(c => isPk(g, c) && g.def(c).types.some(x => tys.includes(x))) ? 4 : 0; } });
def('Hyper Potion', { es: 'Elige 1 de tus Pokémon. Descarta 1 o 2 Energías básicas unidas a él. Si descartas 1, retira hasta 3 contadores de daño; si descartas 2, hasta 5.', can: (g, p) => g.slots(p).some(s => s.dmg > 0 && s.energy.some(c => g.def(c).basic)), play: async (g, p) => { const ts = g.slots(p).filter(s => s.dmg > 0 && s.energy.some(c => g.def(c).basic)); const t = await g.ask(p, { kind: 'slot', title: 'Hiperpoción: elige un Pokémon', options: ts, purpose: 'healOwn' }); const s = t || ts[0]; const be = s.energy.filter(c => g.def(c).basic); const want = s.dmg > 30 && be.length >= 2 ? 2 : 1; const sel = await g.ask(p, { kind: 'cards', title: 'Descarta 1 o 2 Energías básicas', cards: be, min: 1, max: Math.min(2, be.length), purpose: 'discardOwnEnergy', slot: s, want }); for (const c of sel) { g.removeFrom(s.energy, c); g.toDiscard(c); } const h = g.heal(s, sel.length >= 2 ? 50 : 30); g.log(`Hiperpoción cura ${h} a ${g.nm(s)}.`); }, ai: (g, p) => p.active && p.active.dmg >= 40 && g.hpLeft(p.active) <= 30 ? 6 : 0 });
def('Lure Ball', { es: 'Lanza 3 monedas. Por cada cara, elige una carta de Evolución de tu pila de descartes, enséñala y ponla en tu mano.', can: (g, p) => p.discard.some(c => isEvo(g, c)), play: async (g, p) => { const h = await g.flipHeads(p, 3, 'Bola Cebo'); const l = p.discard.filter(c => isEvo(g, c)); const k = Math.min(h, l.length); if (!k) return; const sel = await g.ask(p, { kind: 'cards', title: `Elige ${k} carta(s) de Evolución`, cards: l, min: k, max: k, purpose: 'getAny' }); for (const c of sel) { g.removeFrom(p.discard, c); p.hand.push(c); } }, ai: () => 3 });
// --- Partidarios ---
def("Bill's Maintenance", { es: SUP + 'Si tienes cartas en tu mano, baraja 1 en tu mazo y roba 3 cartas.', can: (g, p, c) => others(p, c).length > 0, play: async (g, p, c) => { const [x] = await g.ask(p, { kind: 'cards', title: 'Mantenimiento de Bill: baraja 1 carta en tu mazo', cards: others(p, c), min: 1, max: 1, purpose: 'discardHand' }); g.removeFrom(p.hand, x); p.deck.push(x); g.shuffleDeck(p); g.draw(p, 3); }, ai: (g, p) => p.deck.length > 6 ? 8 : 0 });
def('Copycat', { es: SUP + 'Baraja tu mano en tu mazo. Luego cuenta las cartas de la mano de tu rival y roba esa misma cantidad.', play: async (g, p, c) => { for (const x of others(p, c)) { g.removeFrom(p.hand, x); p.deck.push(x); } g.shuffleDeck(p); g.draw(p, g.opp(p).hand.length); }, ai: (g, p, c) => g.opp(p).hand.length >= others(p, c).length + 3 && p.deck.length > 10 ? 8 : 0 });
def("Mary's Impulse", { es: SUP + 'Lanza una moneda hasta que salga cruz. Por cada cara, roba 2 cartas.', play: async (g, p) => { const h = await g.flipUntilTails(p, 'Impulso de Mary'); g.draw(p, 2 * h); }, ai: (g, p) => p.deck.length > 8 ? 6 : 0 });
def('Pokémon Nurse', { es: SUP + 'Retira todos los contadores de daño de 1 de tus Pokémon. Luego descarta todas las Energías unidas a él.', can: (g, p) => g.slots(p).some(s => s.dmg > 0), play: async (g, p) => { const ts = g.slots(p).filter(s => s.dmg > 0); const t = await g.ask(p, { kind: 'slot', title: 'Enfermera Pokémon: elige un Pokémon', options: ts, purpose: 'nurse' }); const s = t || ts[0]; g.heal(s, 999); for (const c of s.energy.splice(0)) g.toDiscard(c); g.log(`${g.nm(s)} se cura por completo y descarta sus Energías.`); }, ai: (g, p) => g.slots(p).some(s => g.hpLeft(s) <= 20 && s.dmg >= 50 && s.energy.length <= 1) ? 7 : 0 });
def("Professor Elm's Training Method", { es: SUP + 'Busca en tu mazo una carta de Evolución, enséñala y ponla en tu mano. Baraja tu mazo después.', play: async (g, p) => { await EC().toHandFromDeck(g, p, c => isEvo(g, c), 1, 'Elige una carta de Evolución'); }, ai: (g, p) => p.deck.some(c => isEvo(g, c) && g.slots(p).some(s => g.baseDef(s).name === g.def(c).from)) ? 7 : 0 });
def("Professor Oak's Research", { es: SUP + 'Baraja tu mano en tu mazo y roba 5 cartas.', play: async (g, p, c) => { for (const x of others(p, c)) { g.removeFrom(p.hand, x); p.deck.push(x); } g.shuffleDeck(p); g.draw(p, 5); }, ai: (g, p, c) => others(p, c).length <= 3 && p.deck.length > 8 ? 8 : 0 });
def('Forest Guardian', { es: SUP + 'Baraja tu mazo. Mira las 7 cartas superiores, elige 1, ponla en tu mano y baraja el resto en tu mazo.', play: async (g, p) => { g.shuffleDeck(p); const top = p.deck.slice(-7); if (!top.length) return; const [c] = await g.ask(p, { kind: 'cards', title: 'Guardián del Bosque: elige 1 carta', cards: top, min: 1, max: 1, purpose: 'getAny', fromDeck: true }); g.removeFrom(p.deck, c); p.hand.push(c); g.shuffleDeck(p); }, ai: () => 5 });
def('Juggler', { es: SUP + 'Descarta hasta 2 Energías básicas de tu mano. Si descartas 1, roba 3 cartas. Si descartas 2, roba 5.', can: (g, p) => p.hand.some(c => g.isBasicEnergy(c)), play: async (g, p) => { const l = p.hand.filter(c => g.isBasicEnergy(c)); const sel = await g.ask(p, { kind: 'cards', title: 'Malabarista: descarta 1 o 2 Energías básicas', cards: l, min: 1, max: Math.min(2, l.length), purpose: 'juggler' }); for (const c of sel) { g.removeFrom(p.hand, c); g.toDiscard(c); } g.draw(p, sel.length >= 2 ? 5 : 3); }, ai: (g, p) => p.hand.filter(c => g.isBasicEnergy(c)).length >= 2 && p.deck.length > 8 ? 7 : 0 });
def('Pokémon Fan Club', { es: SUP + 'Busca en tu mazo hasta 2 Pokémon Bebés y/o Básicos y ponlos en tu Banca. Baraja tu mazo después.', can: (g, p) => room(g, p), play: async (g, p) => { await EC().benchFromDeck(g, p, d => d.stage === 0, 2, 'Club de Fans Pokémon: elige un Pokémon Básico o Bebé'); }, ai: (g, p) => p.bench.length < 3 ? 8 : 2 });
def('Seer', { es: SUP + 'Mira las 6 cartas superiores de tu mazo. Toma todas las Energías básicas que haya, enséñalas y ponlas en tu mano. Baraja tu mazo después.', play: async (g, p) => { const top = p.deck.slice(-6); const en = top.filter(c => g.isBasicEnergy(c)); for (const c of en) { g.removeFrom(p.deck, c); p.hand.push(c); } g.shuffleDeck(p); g.log(`Vidente: ${p.name} toma ${en.length} Energía(s).`); }, ai: (g, p) => p.hand.some(c => g.isEnergy(c)) ? 2 : 6 });
def('Town Volunteers', { es: SUP + 'Toma 5 Pokémon Bebés, Básicos, cartas de Evolución y/o Energías básicas de tu pila de descartes, enséñalas y barájalas en tu mazo.', can: (g, p) => p.discard.some(c => isPk(g, c) || g.isBasicEnergy(c)), play: async (g, p) => { const l = p.discard.filter(c => isPk(g, c) || g.isBasicEnergy(c)); const sel = l.length <= 5 ? l : await g.ask(p, { kind: 'cards', title: 'Voluntarios: elige 5 cartas', cards: l, min: 5, max: 5, purpose: 'getAny' }); for (const c of sel) g.removeFrom(p.discard, c); p.deck.push(...sel); g.shuffleDeck(p); g.log(`${sel.length} carta(s) vuelven al mazo.`); }, ai: (g, p) => p.deck.length < 12 ? 6 : 0 });
def('Traveling Salesman', { es: SUP + 'Busca en tu mazo hasta 2 Máquinas Técnicas y/o Herramientas Pokémon, enséñalas y ponlas en tu mano. Baraja tu mazo después.', play: async (g, p) => { await EC().toHandFromDeck(g, p, c => { const s = g.def(c).sub || []; return s.includes('Technical Machine') || s.includes('Pokémon Tool'); }, 2, 'Elige hasta 2 MT/Herramientas'); }, ai: (g, p) => p.deck.some(c => { const s = g.def(c).sub || []; return s.includes('Technical Machine') || s.includes('Pokémon Tool'); }) ? 3 : 0 });
def('Relic Hunter', { es: SUP + 'Busca en tu mazo hasta 2 cartas de Partidario y/o Estadio, enséñalas y ponlas en tu mano. Baraja tu mazo después.', play: async (g, p) => { await EC().toHandFromDeck(g, p, c => { const s = g.def(c).sub || []; return s.includes('Supporter') || s.includes('Stadium'); }, 2, 'Elige hasta 2 Partidarios/Estadios'); }, ai: () => 3 });
def('Apricorn Maker', { es: SUP + 'Busca en tu mazo hasta 2 Entrenadores con "Bola" en su nombre, enséñalos y ponlos en tu mano. Baraja tu mazo después.', play: async (g, p) => { await EC().toHandFromDeck(g, p, c => g.isTrainer(c) && / Ball$/.test(g.def(c).name), 2, 'Elige hasta 2 Bolas'); }, ai: (g, p) => p.deck.some(c => / Ball$/.test(g.def(c).name)) ? 5 : 0 });
def('Desert Shaman', { es: SUP + 'Baraja tu mano en tu mazo y roba hasta 4 cartas. Tu rival hace lo mismo.', play: async (g, p, c) => { for (const pl of [p, g.opp(p)]) { for (const x of (pl === p ? others(p, c) : pl.hand.slice())) { g.removeFrom(pl.hand, x); pl.deck.push(x); } g.shuffleDeck(pl); g.draw(pl, 4); g.log(`${pl.name} baraja su mano y roba 4.`); } }, ai: (g, p, c) => others(p, c).length <= 2 && g.opp(p).hand.length >= 6 ? 8 : 0 });
def('Fisherman', { es: SUP + 'Elige 4 Energías básicas de tu pila de descartes (o todas si hay menos), enséñalas y ponlas en tu mano.', can: (g, p) => p.discard.some(c => g.isBasicEnergy(c)), play: async (g, p) => { const l = p.discard.filter(c => g.isBasicEnergy(c)); const sel = l.length <= 4 ? l : await g.ask(p, { kind: 'cards', title: 'Pescador: elige 4 Energías básicas', cards: l, min: 4, max: 4, purpose: 'getEnergy' }); for (const c of sel) { g.removeFrom(p.discard, c); p.hand.push(c); } g.log(`${p.name} recupera ${sel.length} Energía(s).`); }, ai: (g, p) => p.discard.filter(c => g.isBasicEnergy(c)).length >= 3 && !p.hand.some(c => g.isEnergy(c)) ? 7 : 0 });
def('Oracle', { es: SUP + 'Elige 2 cartas de tu mazo y baraja el resto. Pon las cartas elegidas encima de tu mazo en el orden que quieras.', can: (g, p) => p.deck.length >= 2, play: async (g, p) => { const sel = await g.ask(p, { kind: 'cards', title: 'Oráculo: elige 2 cartas de tu mazo', cards: p.deck.slice(), min: 2, max: 2, purpose: 'getAny', fromDeck: true }); for (const c of sel) g.removeFrom(p.deck, c); g.shuffleDeck(p); const ord = sel.length > 1 ? await g.ask(p, { kind: 'order', title: 'Oráculo: ordena (la primera quedará arriba)', cards: sel, purpose: 'orderOwn' }) : sel; p.deck.push(...(ord || sel).slice().reverse()); }, ai: () => 2 });
def('Underground Expedition', { es: SUP + 'Mira las 4 cartas inferiores de tu mazo. Pon 2 en tu mano y devuelve las demás al fondo de tu mazo en el orden que quieras.', can: (g, p) => p.deck.length > 0, play: async (g, p) => { const bot = p.deck.slice(0, 4); const k = Math.min(2, bot.length); const sel = await g.ask(p, { kind: 'cards', title: 'Expedición Subterránea: elige 2 cartas', cards: bot, min: k, max: k, purpose: 'getAny', fromDeck: true }); for (const c of sel) { g.removeFrom(p.deck, c); p.hand.push(c); } }, ai: (g, p) => p.deck.length > 6 ? 6 : 0 });
